{
  "findings": [
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 Bucket lacks MFA Delete",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is versioned but lacks MFA Delete, making it easier to accidentally or maliciously delete versions without additional security checks."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 Bucket does not have cross-region replication enabled",
      "resource": "aws_s3_bucket.logs",
      "severity": "LOW",
      "explanation": "The S3 bucket does not have cross-region replication configured, which could impact data availability and durability in case of a regional outage."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"
  versioning {
    enabled = true
    mfa_delete = true
  }
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }
  replication_configuration {
    role = aws_iam_role.replication.arn
    rules {
      id     = "replication-rule"
      status = "Enabled"
      destination {
        bucket = "arn:aws:s3:::replication-bucket"
      }
    }
  }
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}",
  "fix_summary": "Enabled MFA Delete on the S3 bucket and added a basic replication configuration to improve data security and availability."
}
